function getDiagramById(id) {
  if (!id) return null;
  return DIAGRAMS_DATA.find(d => d.id === id) || null;
}

function getDiagramsByLevel(level) {
  if (!level || level === 'all') return DIAGRAMS_DATA;
  return DIAGRAMS_DATA.filter(d => d.level === level);
}

// Global exports
window.DIAGRAMS_DATA = DIAGRAMS_DATA;
window.diagramsData = DIAGRAMS_DATA;
window.getDiagramById = getDiagramById;
window.getDiagramsByLevel = getDiagramsByLevel;
